	if opts.ImageFile != "" {
		return "", errors.New(i18n.T("codex_image_file_not_supported"))
	}
	if c.ApiClient == nil {
		if err := c.configure(); err != nil {
			return "", err
		}
	}

	req := c.buildCodexResponseParams(msgs, opts)
	stream := c.ApiClient.Responses.NewStreaming(ctx, req)
	defer stream.Close()

	var (
		builder       strings.Builder
		doneText      string
		completedResp *responses.Response
	)
	for stream.Next() {
		event := stream.Current()
		switch event.Type {
		case string(constant.ResponseOutputTextDelta("").Default()):
			builder.WriteString(event.AsResponseOutputTextDelta().Delta)
		case string(constant.ResponseOutputTextDone("").Default()):
			doneText = event.AsResponseOutputTextDone().Text
		case "response.completed":
			resp := event.AsResponseCompleted().Response
			completedResp = &resp
		}
	}

	if err := c.mapRequestError(stream.Err()); err != nil {
		return "", err
	}
	if completedResp != nil {
		// Codex can omit the output items from response.completed even though it
		// already sent the generated text as deltas. Only prefer the completed
		// response when it actually contains text, otherwise preserve the deltas.
		if text := c.ExtractText(completedResp); text != "" {
			return text, nil
		}
	}
	if builder.Len() > 0 {
		return builder.String(), nil
	}

	// Some Codex streams only include the complete text in the terminal done
	// event. It is safe to use here because no deltas were available.
	return doneText, nil
}

// SendStream sends a request to Codex and streams the response text updates.
func (c *Client) SendStream(
	ctx context.Context, msgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions, channel chan domain.StreamUpdate,
) error {
	defer close(channel)

	if opts.ImageFile != "" {
		return errors.New(i18n.T("codex_image_file_not_supported"))
	}
	if c.ApiClient == nil {
		if err := c.configure(); err != nil {
			return err
		}
	}

	req := c.buildCodexResponseParams(msgs, opts)
	stream := c.ApiClient.Responses.NewStreaming(ctx, req)
	defer stream.Close()
	emittedText := false
	for stream.Next() {
		event := stream.Current()
		switch event.Type {
		case string(constant.ResponseOutputTextDelta("").Default()):
			delta := event.AsResponseOutputTextDelta().Delta
			if delta == "" {
				continue
			}
			if err := sendStreamUpdate(ctx, channel, domain.StreamUpdate{
				Type:    domain.StreamTypeContent,
				Content: delta,
			}); err != nil {
				return err
			}
			emittedText = true
		case string(constant.ResponseOutputTextDone("").Default()):
			// The done event normally repeats previously streamed deltas. When
			// Codex omits those deltas, use its full text instead of returning an
			// apparently successful empty response.
			if emittedText {
				continue
			}
			text := event.AsResponseOutputTextDone().Text
			if text == "" {
				continue
			}
			if err := sendStreamUpdate(ctx, channel, domain.StreamUpdate{
				Type:    domain.StreamTypeContent,
				Content: text,
			}); err != nil {
				return err
			}
			emittedText = true
		}
	}

	if stream.Err() == nil {
		if err := sendStreamUpdate(ctx, channel, domain.StreamUpdate{
			Type:    domain.StreamTypeContent,
			Content: "\n",
		}); err != nil {
			return err
		}
	}

	return c.mapRequestError(stream.Err())
}

func sendStreamUpdate(ctx context.Context, channel chan domain.StreamUpdate, update domain.StreamUpdate) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	case channel <- update:
		return nil
	}
}


